from pathlib import Path
import json,copy,numpy as np,math,hashlib
root=Path.cwd();r=Path(__file__).resolve().parent;spec=json.loads((r/'camera-candidate.json').read_text());source=root/'build/runs/20261031-105539-full-scene-character-composition-b37668/project';original=json.loads((source/'scene/full-character-visible.azurelevel').read_text());checks=[]
x,y,z=np.radians(spec['cameraRotationDegrees']);rx=np.array([[1,0,0],[0,math.cos(x),math.sin(x)],[0,-math.sin(x),math.cos(x)]]);ry=np.array([[math.cos(y),0,math.sin(y)],[0,1,0],[-math.sin(y),0,math.cos(y)]]);rz=np.array([[math.cos(z),math.sin(z),0],[-math.sin(z),math.cos(z),0],[0,0,1]]);actual=rx@ry@rz;expected=np.array(spec['meanWorldIrisNormal']);assert np.max(np.abs(actual[:,2]-expected))<1e-12;assert abs(np.linalg.norm(np.array(spec['worldIrisCenter'])-np.array(spec['cameraPosition']))-.85)<1e-12
for row in spec['cases']:
 project=root/row['project'];d=json.loads(project.read_text());assert all((project.parent/m['path']).resolve().is_relative_to(project.parent.resolve()) for m in d['mounts']);level=project.parent/'scene'/('frontal-'+row['name']+'.azurelevel');candidate=json.loads(level.read_text());assert hashlib.sha256(level.read_bytes()).hexdigest()==row['levelSha256'];restored=copy.deepcopy(candidate);restored['renderSettings']['antiAliasing']=original['renderSettings']['antiAliasing'];restored['renderSettings']['nprLighting']=copy.deepcopy(original['renderSettings']['nprLighting']);camera=next(n for n in restored['nodes'] if n['id']=='camera');camera['components']=copy.deepcopy(next(n['components'] for n in original['nodes'] if n['id']=='camera'));assert restored==original;checks.append(dict(case=row['name'],status='passed',projectSha256=hashlib.sha256(project.read_bytes()).hexdigest(),levelSha256=hashlib.sha256(level.read_bytes()).hexdigest()))
files=json.loads((r/'asset-copy.json').read_text())['records'];sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();identities=[]
for row in files:
 p=source/row['path'];q=r/'project'/row['path'];a=sha(p);assert a==sha(q);identities.append(dict(path=row['path'],bytes=q.stat().st_size,sha256=a))
report=dict(status='scene-and-camera-inputs-verified',cases=checks,sourceAssetFilesVerified=len(identities),sourceAssetFiles=identities,cameraForwardNormalError=float(np.max(np.abs(actual[:,2]-expected))),scope='Scene integrity and CPU-derived camera only; visual review and production camera report remain pending.');(r/'input-verification.json').write_text(json.dumps(report,indent=2)+'\n');print(report['status'],len(identities),'files')
